SELECT NVL(SM_VENDOR_NAME, VENDOR_NAME) AS VENDOR_NAME ,A.VENDOR_CODE ,A.SUM_VALUE AS TOOLTIP_VAL ,TRUNC(A.SUM_VALUE / B.TOT_VALUE * 100) AS SUM_VALUE FROM (SELECT VN.VENDOR_NAME AS VENDOR_NAME ,A.VENDOR_CODE ,A.VENDOR_NAME AS SM_VENDOR_NAME ,SUM(A.CSTMS + A.INTTAX + A.ECX_AMOUNT + A.AGSPT + A.TRANTAX + A.LQTX_AMOUNT) AS SUM_VALUE ,RANK() OVER(ORDER BY SUM(A.CSTMS + A.INTTAX + A.ECX_AMOUNT + A.AGSPT + A.TRANTAX + A.LQTX_AMOUNT) DESC) AS RK FROM INCME_LOCAL_BNT_SM A LEFT OUTER JOIN VENDOR VN ON A.COMPANY_CODE = VN.COMPANY_CODE AND A.VENDOR_CODE = VN.VENDOR_CODE WHERE A.COMPANY_CODE = #{COMPANY_CODE} AND A.EFECT_BGNDE BETWEEN #{SEARCH_FROM_DATE} AND #{SEARCH_TO_DATE}
AND A.RAWMTRL_SE = #{RAWMTRL_SE}
AND A.ITEM_CODE= #{SEARCH_KEY_WORD}
AND A.ITEM_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND A.ITEM_CODE LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
AND A.IMPDEC_NO= #{SEARCH_KEY_WORD}
AND A.IMPDEC_NO LIKE #{SEARCH_KEY_WORD}|| '%'
AND A.IMPDEC_NO LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
GROUP BY VN.VENDOR_NAME ,A.VENDOR_CODE ,A.VENDOR_NAME) A INNER JOIN (SELECT SUM(A.CSTMS + A.INTTAX + A.ECX_AMOUNT + A.AGSPT + A.TRANTAX + A.LQTX_AMOUNT) AS TOT_VALUE ,1 AS RK FROM INCME_LOCAL_BNT_SM A LEFT OUTER JOIN VENDOR VN ON A.COMPANY_CODE = VN.COMPANY_CODE AND A.VENDOR_CODE = VN.VENDOR_CODE WHERE A.COMPANY_CODE = #{COMPANY_CODE} AND A.EFECT_BGNDE BETWEEN #{SEARCH_FROM_DATE} AND #{SEARCH_TO_DATE}) B ON 1 = 1 WHERE A.RK < 6

SELECT NVL(SM_VENDOR_NAME,VENDOR_NAME) AS VENDOR_NAME ,VENDOR_CODE ,SUM_VALUE FROM (SELECT VN.VENDOR_NAME AS VENDOR_NAME ,A.VENDOR_CODE ,A.VENDOR_NAME AS SM_VENDOR_NAME ,SUM(A.REMNDR_QY) AS SUM_VALUE ,RANK() OVER(ORDER BY SUM(A.REMNDR_QY) DESC) AS RK FROM INCME_LOCAL_BNT_SM A LEFT OUTER JOIN VENDOR VN ON A.COMPANY_CODE = VN.COMPANY_CODE AND A.VENDOR_CODE = VN.VENDOR_CODE WHERE A.COMPANY_CODE = #{COMPANY_CODE} AND A.EFECT_BGNDE BETWEEN #{SEARCH_FROM_DATE} AND #{SEARCH_TO_DATE}
AND A.RAWMTRL_SE = #{RAWMTRL_SE}
AND A.ITEM_CODE= #{SEARCH_KEY_WORD}
AND A.ITEM_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND A.ITEM_CODE LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
AND A.IMPDEC_NO= #{SEARCH_KEY_WORD}
AND A.IMPDEC_NO LIKE #{SEARCH_KEY_WORD}|| '%'
AND A.IMPDEC_NO LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
GROUP BY VN.VENDOR_NAME ,A.VENDOR_CODE, A.VENDOR_NAME) WHERE RK < 6

SELECT ITEM_CODE ,ITEM_NM ,SUM_VALUE FROM (SELECT A.ITEM_CODE ,A.ITEM_NM ,ROUND(SUM(A.CSTMS), 0) AS SUM_VALUE ,RANK() OVER(ORDER BY ROUND(SUM(A.REMNDR_QY), 0) DESC) AS RK FROM INCME_LOCAL_BNT_SM A LEFT OUTER JOIN VENDOR VN ON A.COMPANY_CODE = VN.COMPANY_CODE AND A.VENDOR_CODE = VN.VENDOR_CODE WHERE A.COMPANY_CODE = #{COMPANY_CODE} AND A.EFECT_BGNDE BETWEEN #{SEARCH_FROM_DATE} AND #{SEARCH_TO_DATE}
AND A.RAWMTRL_SE = #{RAWMTRL_SE}
AND A.ITEM_CODE= #{SEARCH_KEY_WORD}
AND A.ITEM_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND A.ITEM_CODE LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
AND A.IMPDEC_NO= #{SEARCH_KEY_WORD}
AND A.IMPDEC_NO LIKE #{SEARCH_KEY_WORD}|| '%'
AND A.IMPDEC_NO LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
GROUP BY A.ITEM_CODE ,A.ITEM_NM) WHERE RK < 6

SELECT ITEM_CODE ,ITEM_NM ,SUM_VALUE AS TOOLTIP_VAL ,TRUNC(A.SUM_VALUE / B.TOT_VALUE * 100) AS SUM_VALUE FROM (SELECT A.ITEM_CODE ,A.ITEM_NM ,ROUND(SUM(A.REMNDR_QY), 0) AS SUM_VALUE ,RANK() OVER(ORDER BY ROUND(SUM(A.REMNDR_QY), 0) DESC) AS RK FROM INCME_LOCAL_BNT_SM A WHERE A.COMPANY_CODE = #{COMPANY_CODE} AND A.EFECT_BGNDE BETWEEN #{SEARCH_FROM_DATE} AND #{SEARCH_TO_DATE}
AND A.RAWMTRL_SE = #{RAWMTRL_SE}
AND A.ITEM_CODE= #{SEARCH_KEY_WORD}
AND A.ITEM_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND A.ITEM_CODE LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
AND A.IMPDEC_NO= #{SEARCH_KEY_WORD}
AND A.IMPDEC_NO LIKE #{SEARCH_KEY_WORD}|| '%'
AND A.IMPDEC_NO LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
GROUP BY A.ITEM_CODE ,A.ITEM_NM) A INNER JOIN (SELECT SUM(A.REMNDR_QY) AS TOT_VALUE FROM INCME_LOCAL_BNT_SM A WHERE A.COMPANY_CODE = #{COMPANY_CODE}
AND A.EFECT_BGNDE BETWEEN #{SEARCH_FROM_DATE} AND #{SEARCH_TO_DATE}) B ON 1 = 1 WHERE RK < 6

SELECT HS_CODE ,SUM_VALUE FROM (SELECT A.HS_CODE ,ROUND(SUM(A.CSTMS), 0) AS SUM_VALUE ,RANK() OVER(ORDER BY ROUND(SUM(A.REMNDR_QY), 0) DESC) AS RK FROM INCME_LOCAL_BNT_SM A LEFT OUTER JOIN VENDOR VN ON A.COMPANY_CODE = VN.COMPANY_CODE AND A.VENDOR_CODE = VN.VENDOR_CODE WHERE A.COMPANY_CODE = #{COMPANY_CODE} AND A.EFECT_BGNDE BETWEEN #{SEARCH_FROM_DATE} AND #{SEARCH_TO_DATE}
AND A.RAWMTRL_SE = #{RAWMTRL_SE}
AND A.ITEM_CODE= #{SEARCH_KEY_WORD}
AND A.ITEM_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND A.ITEM_CODE LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
AND A.IMPDEC_NO= #{SEARCH_KEY_WORD}
AND A.IMPDEC_NO LIKE #{SEARCH_KEY_WORD}|| '%'
AND A.IMPDEC_NO LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
GROUP BY A.HS_CODE ) WHERE RK < 6

/* hsCode_balanceQty_Barchartdiv :: rpt002_getHsCodeBalanceQty */
SELECT A.HS_CODE ,SUM_VALUE AS TOOLTIP_VAL ,TRUNC(A.SUM_VALUE / B.TOT_VALUE * 100) AS SUM_VALUE FROM (SELECT A.HS_CODE ,ROUND(SUM(A.REMNDR_QY), 0) AS SUM_VALUE ,RANK() OVER(ORDER BY ROUND(SUM(A.REMNDR_QY), 0) DESC) AS RK FROM INCME_LOCAL_BNT_SM A WHERE A.COMPANY_CODE = #{COMPANY_CODE} AND A.EFECT_BGNDE BETWEEN #{SEARCH_FROM_DATE} AND #{SEARCH_TO_DATE}
AND A.RAWMTRL_SE = #{RAWMTRL_SE}
AND A.ITEM_CODE= #{SEARCH_KEY_WORD}
AND A.ITEM_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND A.ITEM_CODE LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
AND A.IMPDEC_NO= #{SEARCH_KEY_WORD}
AND A.IMPDEC_NO LIKE #{SEARCH_KEY_WORD}|| '%'
AND A.IMPDEC_NO LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
GROUP BY A.HS_CODE) A INNER JOIN (SELECT SUM(A.REMNDR_QY) AS TOT_VALUE FROM INCME_LOCAL_BNT_SM A WHERE A.COMPANY_CODE = #{COMPANY_CODE} AND A.EFECT_BGNDE BETWEEN #{SEARCH_FROM_DATE} AND #{SEARCH_TO_DATE}) B ON 1 = 1
WHERE A.RK < 6

SELECT A.IMPDEC_NO ,VN.VENDOR_NAME ,A.EFECT_BGNDE ,SUM((A.CSTMS + A.INTTAX + A.ECX_AMOUNT + A.AGSPT + A.TRANTAX + A.LQTX_AMOUNT)) AS TOT_TAX ,ROUND(SUM((A.CSTMS + A.INTTAX + A.ECX_AMOUNT + A.AGSPT + A.TRANTAX + A.LQTX_AMOUNT) / A.QY * A.REMNDR_QY), 0) AS REMND_TAX ,SUM(A.QY) AS QY ,SUM(A.REMNDR_QY) AS REMNDR_QY ,TO_CHAR(ADD_MONTHS(TO_DATE(A.EFECT_BGNDE, 'RRRRMMDD'), 12) - 1, 'RRRRMMDD') AS EXPR_DATE FROM INCME_LOCAL_BNT_SM A LEFT OUTER JOIN VENDOR VN ON A.COMPANY_CODE = VN.COMPANY_CODE AND A.VENDOR_CODE = VN.VENDOR_CODE WHERE A.COMPANY_CODE = #{COMPANY_CODE} AND A.EFECT_BGNDE BETWEEN #{SEARCH_FROM_DATE} AND #{SEARCH_TO_DATE}
AND A.RAWMTRL_SE = #{RAWMTRL_SE}
AND A.ITEM_CODE= #{SEARCH_KEY_WORD}
AND A.ITEM_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND A.ITEM_CODE LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
AND A.IMPDEC_NO= #{SEARCH_KEY_WORD}
AND A.IMPDEC_NO LIKE #{SEARCH_KEY_WORD}|| '%'
AND A.IMPDEC_NO LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
AND A.RAWMTRL_SE = '02' /* 02: 기초납입증명서 */ AND A.REMNDR_QY > 0 GROUP BY A.IMPDEC_NO,VN.VENDOR_NAME,A.EFECT_BGNDE

SELECT A.IMPDEC_NO ,VN.VENDOR_NAME ,A.EFECT_BGNDE ,SUM((A.CSTMS + A.INTTAX + A.ECX_AMOUNT + A.AGSPT + A.TRANTAX + A.LQTX_AMOUNT)) AS TOT_TAX ,ROUND(SUM((A.CSTMS + A.INTTAX + A.ECX_AMOUNT + A.AGSPT + A.TRANTAX + A.LQTX_AMOUNT) / A.QY * A.REMNDR_QY), 0) AS REMND_TAX ,SUM(A.QY) AS QY ,SUM(A.REMNDR_QY) AS REMNDR_QY ,TO_CHAR(LAST_DAY(ADD_MONTHS(TO_DATE(A.EFECT_BGNDE, 'RRRRMMDD'), 23)), 'RRRRMMDD') AS EXPR_DATE FROM INCME_LOCAL_BNT_SM A LEFT OUTER JOIN VENDOR VN ON A.COMPANY_CODE = VN.COMPANY_CODE AND A.VENDOR_CODE = VN.VENDOR_CODE WHERE A.COMPANY_CODE = #{COMPANY_CODE} AND A.EFECT_BGNDE BETWEEN #{SEARCH_FROM_DATE} AND #{SEARCH_TO_DATE} AND A.RAWMTRL_SE IN ('04','00') /* 00: 수입신고필증, 04: 분할증명서 */
AND A.RAWMTRL_SE = #{RAWMTRL_SE}
AND A.ITEM_CODE= #{SEARCH_KEY_WORD}
AND A.ITEM_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND A.ITEM_CODE LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
AND A.IMPDEC_NO= #{SEARCH_KEY_WORD}
AND A.IMPDEC_NO LIKE #{SEARCH_KEY_WORD}|| '%'
AND A.IMPDEC_NO LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
AND A.REMNDR_QY > 0 GROUP BY A.IMPDEC_NO,VN.VENDOR_NAME,A.EFECT_BGNDE

SELECT A.IMPDEC_NO ,NVL(B.VENDOR_NAME, C.VENDOR_NAME) VENDOR_NAME ,A.ITEM_CODE ,NVL(B.ITEM_NM, C.ITEM_NM) AS ITEM_NM ,A.HS_CODE ,A.EFECT_BGNDE ,CASE WHEN A.RAWMTRL_SE = '02' THEN TO_CHAR(ADD_MONTHS(TO_DATE(A.EFECT_BGNDE, 'RRRRMMDD'), 12)-1, 'RRRRMMDD') ELSE TO_CHAR(LAST_DAY(ADD_MONTHS(TO_DATE(A.EFECT_BGNDE, 'RRRRMMDD'), 23)), 'RRRRMMDD') END AS EXPR_DATE ,A.RAWMTRL_SE ,CC.CODE_NM AS RAWMTRL_SE_NAME ,NVL(B.SETLE_AMOUNT, C.PO_AMOUNT) AS PO_AMOUNT ,(A.CSTMS + A.INTTAX + A.ECX_AMOUNT + A.AGSPT + A.TRANTAX + A.LQTX_AMOUNT) AS TOT_TAX ,ROUND((A.CSTMS + A.INTTAX + A.ECX_AMOUNT + A.AGSPT + A.TRANTAX + A.LQTX_AMOUNT) / A.QY * A.REMNDR_QY, 0) AS REMND_TAX ,A.QY ,A.REMNDR_QY
FROM INCME_LOCAL_BNT_SM A
LEFT OUTER JOIN ITEM_MST IM ON A.COMPANY_CODE = IM.COMPANY_CODE AND A.ITEM_CODE = IM.ITEM_CODE /* 수입면장 정보 */ LEFT OUTER JOIN (SELECT I.* ,B.SETLE_AMOUNT ,B.SUPLER_MTLTY_1 AS VENDOR_NAME FROM IMPDEC_CERFIN_HDER B INNER JOIN IMPDEC_CERFIN_ITEM I ON B.COMPANY_CODE = I.COMPANY_CODE AND B.DIVISION_CODE = I.DIVISION_CODE AND B.IMPDEC_MANAGE_NO = I.IMPDEC_MANAGE_NO) B ON A.COMPANY_CODE = B.COMPANY_CODE AND A.DIVISION_CODE = B.DIVISION_CODE AND A.IMPDEC_NO = B.IMPDEC_NO AND A.LNE_NO = B.LNE_NO AND A.POUCH_NO = B.POUCH_NO /* 기초납입 + 분할 증명서 정보 */ LEFT OUTER JOIN (SELECT C.* , V.VENDOR_NAME FROM CCPY_CSTMR_DMSTC C LEFT OUTER JOIN VENDOR V ON C.COMPANY_CODE = V.COMPANY_CODE AND C.VENDOR_CODE = V.VENDOR_CODE) C ON A.COMPANY_CODE = C.COMPANY_CODE AND A.DIVISION_CODE = C.DIVISION_CODE AND A.IMPDEC_NO = C.CTRM_REGIST_NO AND A.ITEM_CODE = C.ITEM_CODE AND A.LNE_NO = C.LNE_NO AND A.POUCH_NO = C.POUCH_NO LEFT OUTER JOIN COM_CD CC ON CC.CATEGORY_CD = 'LMC' AND CC.CODE_CD = A.RAWMTRL_SE WHERE A.COMPANY_CODE = #{COMPANY_CODE} AND A.EFECT_BGNDE BETWEEN #{SEARCH_FROM_DATE} AND #{SEARCH_TO_DATE}
AND A.RAWMTRL_SE = #{RAWMTRL_SE}
AND A.ITEM_CODE= #{SEARCH_KEY_WORD}
AND A.ITEM_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND A.ITEM_CODE LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
AND A.IMPDEC_NO= #{SEARCH_KEY_WORD}
AND A.IMPDEC_NO LIKE #{SEARCH_KEY_WORD}|| '%'
AND A.IMPDEC_NO LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
AND A.REMNDR_QY > 0 AND A.VENDOR_CODE = #{KEY_VENDOR_CODE}

SELECT A.IMPDEC_NO ,NVL(B.VENDOR_NAME, C.VENDOR_NAME) AS VENDOR_NAME ,A.ITEM_CODE ,NVL(B.ITEM_NM, C.ITEM_NM) AS ITEM_NM ,A.HS_CODE ,A.EFECT_BGNDE ,CASE WHEN A.RAWMTRL_SE = '02' THEN TO_CHAR(ADD_MONTHS(TO_DATE(A.EFECT_BGNDE, 'RRRRMMDD'), 12)-1, 'RRRRMMDD') ELSE TO_CHAR(LAST_DAY(ADD_MONTHS(TO_DATE(A.EFECT_BGNDE, 'RRRRMMDD'), 23)), 'RRRRMMDD') END AS EXPR_DATE ,A.RAWMTRL_SE ,CC.CODE_NM AS RAWMTRL_SE_NAME ,NVL(B.CVODV_KRW, C.PO_AMOUNT) AS PO_AMOUNT ,(A.CSTMS + A.INTTAX + A.ECX_AMOUNT + A.AGSPT + A.TRANTAX + A.LQTX_AMOUNT) AS TOT_TAX ,ROUND((A.CSTMS + A.INTTAX + A.ECX_AMOUNT + A.AGSPT + A.TRANTAX + A.LQTX_AMOUNT) / A.QY * A.REMNDR_QY, 0) AS REMND_TAX ,A.QY ,A.REMNDR_QY
FROM INCME_LOCAL_BNT_SM A
LEFT OUTER JOIN ITEM_MST IM ON A.COMPANY_CODE = IM.COMPANY_CODE AND A.ITEM_CODE = IM.ITEM_CODE /* 수입면장 정보 */ LEFT OUTER JOIN (SELECT I.* ,B.SUPLER_MTLTY_1 AS VENDOR_NAME FROM IMPDEC_CERFIN_HDER B INNER JOIN IMPDEC_CERFIN_ITEM I ON B.COMPANY_CODE = I.COMPANY_CODE AND B.DIVISION_CODE = I.DIVISION_CODE AND B.IMPDEC_MANAGE_NO = I.IMPDEC_MANAGE_NO LEFT OUTER JOIN VENDOR V ON B.COMPANY_CODE = V.COMPANY_CODE AND B.VENDOR_CODE = V.VENDOR_CODE) B ON A.COMPANY_CODE = B.COMPANY_CODE AND A.DIVISION_CODE = B.DIVISION_CODE AND A.IMPDEC_NO = B.IMPDEC_NO AND A.LNE_NO = B.LNE_NO AND A.POUCH_NO = B.POUCH_NO /* 기초납입 + 분할 증명서 정보 */ LEFT OUTER JOIN (SELECT C.* ,V.VENDOR_NAME FROM CCPY_CSTMR_DMSTC C LEFT OUTER JOIN VENDOR V ON C.COMPANY_CODE = V.COMPANY_CODE AND C.VENDOR_CODE = V.VENDOR_CODE) C ON A.COMPANY_CODE = C.COMPANY_CODE AND A.DIVISION_CODE = C.DIVISION_CODE AND A.IMPDEC_NO = C.CTRM_REGIST_NO AND A.ITEM_CODE = C.ITEM_CODE AND A.LNE_NO = C.LNE_NO AND A.POUCH_NO = C.POUCH_NO LEFT OUTER JOIN COM_CD CC ON CC.CATEGORY_CD = 'LMC' AND CC.CODE_CD = A.RAWMTRL_SE WHERE A.COMPANY_CODE = #{COMPANY_CODE} AND A.EFECT_BGNDE BETWEEN #{SEARCH_FROM_DATE} AND #{SEARCH_TO_DATE} AND A.REMNDR_QY > 0 AND A.ITEM_CODE = #{KEY_VENDOR_CODE} AND NVL(B.ITEM_NM, C.ITEM_NM) = #{KEY_CODE_DETAIL}
AND A.RAWMTRL_SE = #{RAWMTRL_SE}
AND A.ITEM_CODE= #{SEARCH_KEY_WORD}
AND A.ITEM_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND A.ITEM_CODE LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
AND A.IMPDEC_NO= #{SEARCH_KEY_WORD}
AND A.IMPDEC_NO LIKE #{SEARCH_KEY_WORD}|| '%'
AND A.IMPDEC_NO LIKE '%'||#{SEARCH_KEY_WORD}|| '%'

SELECT A.IMPDEC_NO ,NVL(B.VENDOR_NAME, C.VENDOR_NAME) AS VENDOR_NAME ,A.ITEM_CODE ,NVL(B.ITEM_NM, C.ITEM_NM) AS ITEM_NM ,A.HS_CODE ,A.EFECT_BGNDE ,NVL(B.CVODV_KRW, C.PO_AMOUNT) AS PO_AMOUNT ,(A.CSTMS + A.INTTAX + A.ECX_AMOUNT + A.AGSPT + A.TRANTAX + A.LQTX_AMOUNT) AS TOT_TAX ,ROUND((A.CSTMS + A.INTTAX + A.ECX_AMOUNT + A.AGSPT + A.TRANTAX + A.LQTX_AMOUNT) / A.QY * A.REMNDR_QY, 0) AS REMND_TAX ,A.QY ,A.RAWMTRL_SE ,CC.CODE_NM AS RAWMTRL_SE_NAME ,A.REMNDR_QY
FROM INCME_LOCAL_BNT_SM A
LEFT OUTER JOIN ITEM_MST IM ON A.COMPANY_CODE = IM.COMPANY_CODE AND A.ITEM_CODE = IM.ITEM_CODE /* 수입면장 정보 */ LEFT OUTER JOIN (SELECT I.* ,B.SUPLER_MTLTY_1 AS VENDOR_NAME FROM IMPDEC_CERFIN_HDER B INNER JOIN IMPDEC_CERFIN_ITEM I ON B.COMPANY_CODE = I.COMPANY_CODE AND B.DIVISION_CODE = I.DIVISION_CODE AND B.IMPDEC_MANAGE_NO = I.IMPDEC_MANAGE_NO LEFT OUTER JOIN VENDOR V ON B.COMPANY_CODE = V.COMPANY_CODE AND B.VENDOR_CODE = V.VENDOR_CODE) B ON A.COMPANY_CODE = B.COMPANY_CODE AND A.DIVISION_CODE = B.DIVISION_CODE AND A.IMPDEC_NO = B.IMPDEC_NO AND A.LNE_NO = B.LNE_NO AND A.POUCH_NO = B.POUCH_NO /* 기초납입 + 분할 증명서 정보 */ LEFT OUTER JOIN (SELECT C.* ,V.VENDOR_NAME FROM CCPY_CSTMR_DMSTC C LEFT OUTER JOIN VENDOR V ON C.COMPANY_CODE = V.COMPANY_CODE AND C.VENDOR_CODE = V.VENDOR_CODE) C ON A.COMPANY_CODE = C.COMPANY_CODE AND A.DIVISION_CODE = C.DIVISION_CODE AND A.IMPDEC_NO = C.CTRM_REGIST_NO AND A.ITEM_CODE = C.ITEM_CODE AND A.LNE_NO = C.LNE_NO AND A.POUCH_NO = C.POUCH_NO LEFT OUTER JOIN COM_CD CC ON CC.CATEGORY_CD = 'LMC' AND CC.CODE_CD = A.RAWMTRL_SE WHERE A.COMPANY_CODE = #{COMPANY_CODE} AND A.EFECT_BGNDE BETWEEN #{SEARCH_FROM_DATE} AND #{SEARCH_TO_DATE} AND A.REMNDR_QY > 0 AND A.HS_CODE = #{KEY_VENDOR_CODE}
AND A.RAWMTRL_SE = #{RAWMTRL_SE}
AND A.ITEM_CODE= #{SEARCH_KEY_WORD}
AND A.ITEM_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND A.ITEM_CODE LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
AND A.IMPDEC_NO= #{SEARCH_KEY_WORD}
AND A.IMPDEC_NO LIKE #{SEARCH_KEY_WORD}|| '%'
AND A.IMPDEC_NO LIKE '%'||#{SEARCH_KEY_WORD}|| '%'

/* Top 5 rpt008_getVendorDrwbak_Rate */ SELECT LST.LABEL_VALUE ,LST.CODE_VALUE ,LST.TOOLTIP_VAL ,LST.DATA_VALUE FROM (SELECT A.LABEL_VALUE ,A.CODE_VALUE ,A.DATA_VALUE AS TOOLTIP_VAL
,DECODE(B.TOT_VALUE,0,0,ROUND(A.DATA_VALUE / B.TOT_VALUE * 10000,2)) AS DATA_VALUE ,RANK() OVER(ORDER BY A.DATA_VALUE DESC) AS RK FROM (SELECT A.MANUFAC_NAME AS LABEL_VALUE ,A.MANUFAC_NAME AS CODE_VALUE ,MAX(A.DRWBAK_AMOUNT) AS DATA_VALUE FROM EXPORT_CERT_MST M LEFT OUTER JOIN DRWBAK_REQSTDOC_TRGET_THNG B ON M.COMPANY_CODE = B.COMPANY_CODE AND M.DIVISION_CODE = B.DIVISION_CODE AND M.XPORT_STTEMNT_NO = B.XPORT_STTEMNT_NO AND M.LNE_NO = B.LNE_NO AND M.POUCH_NO = B.POUCH_NO AND M.ITEM_CODE = B.ITEM_CODE LEFT OUTER JOIN DRWBAK_REQSTDOC_CMMN A ON A.PRESENTN_NO = B.PRESENTN_NO AND A.COMPANY_CODE = B.COMPANY_CODE WHERE A.COMPANY_CODE = #{COMPANY_CODE} AND M.DSPTH_DATE BETWEEN #{SEARCH_FROM_DATE} AND #{SEARCH_TO_DATE}
AND M.ITEM_CODE= #{SEARCH_KEY_WORD}
AND M.ITEM_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND M.ITEM_CODE LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
GROUP BY A.MANUFAC_NAME) A INNER JOIN (SELECT SUM(NVL(M.STTEMNT_PC_KRW, 0)) AS TOT_VALUE FROM EXPORT_CERT_MST M LEFT OUTER JOIN DRWBAK_REQSTDOC_TRGET_THNG B ON M.COMPANY_CODE = B.COMPANY_CODE AND M.DIVISION_CODE = B.DIVISION_CODE AND M.XPORT_STTEMNT_NO = B.XPORT_STTEMNT_NO AND M.LNE_NO = B.LNE_NO AND M.POUCH_NO = B.POUCH_NO AND M.ITEM_CODE = B.ITEM_CODE LEFT OUTER JOIN DRWBAK_REQSTDOC_CMMN A ON A.PRESENTN_NO = B.PRESENTN_NO AND A.COMPANY_CODE = B.COMPANY_CODE WHERE A.COMPANY_CODE = #{COMPANY_CODE} AND M.DSPTH_DATE BETWEEN #{SEARCH_FROM_DATE} AND #{SEARCH_TO_DATE}) B ON 1 = 1) LST WHERE LST.RK < 6

/* Top 5 rpt008_getVendorDrwbakUsedQtyData */ SELECT LABEL_VALUE ,CODE_VALUE ,DATA_VALUE ,RK FROM (SELECT NVL(A.SUPLER_MTLTY_1,V.VENDOR_NAME) AS LABEL_VALUE ,A.VENDOR_CODE AS CODE_VALUE ,DECODE(SUM(L.QY),0,0,ROUND(SUM(L.DLIVY_QY) / SUM(L.QY), 4) * 100) AS DATA_VALUE ,RANK() OVER(ORDER BY(SUM(L.DLIVY_QY) / SUM(L.QY)) DESC) AS RK FROM IMPDEC_CERFIN_HDER A INNER JOIN IMPDEC_CERFIN_ITEM B ON A.COMPANY_CODE = B.COMPANY_CODE AND A.DIVISION_CODE = B.DIVISION_CODE AND A.IMPDEC_NO = B.IMPDEC_NO INNER JOIN INCME_LOCAL_BNT_SM L ON B.COMPANY_CODE = L.COMPANY_CODE AND B.DIVISION_CODE = L.DIVISION_CODE AND B.IMPDEC_NO = L.IMPDEC_NO AND B.LNE_NO = L.LNE_NO AND B.POUCH_NO = L.POUCH_NO LEFT OUTER JOIN VENDOR V ON A.COMPANY_CODE = V.COMPANY_CODE AND A.VENDOR_CODE = V.VENDOR_CODE WHERE A.VENDOR_CODE IS NOT NULL AND A.COMPANY_CODE = #{COMPANY_CODE} AND A.STTEMNT_DATE BETWEEN #{SEARCH_FROM_DATE} AND #{SEARCH_TO_DATE}
AND B.ITEM_CODE= #{SEARCH_KEY_WORD}
AND B.ITEM_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND B.ITEM_CODE LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
GROUP BY A.VENDOR_CODE , NVL(A.SUPLER_MTLTY_1,V.VENDOR_NAME)) WHERE RK < 6

