UNION ALL SELECT '기납증/분증' AS LABEL_VALUE ,'CTRM' AS CODE_VALUE ,NVL(SUM(TT.STTEMNT_PC_KRW),0) + NVL(SUM(TR.STTEMNT_PC_KRW),0) AS DATA_VALUE FROM SUPT_DOC_HDR A INNER JOIN SUPT_DOC_ITEM B ON A.COMPANY_CODE = B.COMPANY_CODE AND A.DIVISION_CODE = B.DIVISION_CODE AND A.SUPT_DOC_CODE = B.SUPT_DOC_CODE INNER JOIN CUSTOMER_MODEL CM ON B.COMPANY_CODE = CM.COMPANY_CODE AND B.DIVISION_CODE = CM.DIVISION_CODE AND A.CUSTOMER_CODE = CM.CUSTOMER_CODE AND B.ITEM_CODE = CM.CUSTOMER_ITEM_CODE LEFT OUTER JOIN CTRM_TRGET_THNG TT ON A.COMPANY_CODE = TT.COMPANY_CODE AND A.DIVISION_CODE = TT.DIVISION_CODE AND CM.ITEM_CODE = TT.ITEM_CODE AND A.SUPT_DOC_NO = TT.BASIS_DOC_NO LEFT OUTER JOIN CTRM_THING_RAWMTRL TR ON A.COMPANY_CODE = TR.COMPANY_CODE AND A.DIVISION_CODE = TR.DIVISION_CODE AND CM.ITEM_CODE = TR.RAWMTRL_CODE AND A.SUPT_DOC_NO = TR.BASIS_DOC_NO WHERE A.SUPT_DATE BETWEEN #{SEARCH_FROM_DATE} AND #{SEARCH_TO_DATE} AND HS_CODE10 IS NOT NULL AND LENGTH(HS_CODE10) = 10 AND A.COMPANY_CODE = #{COMPANY_CODE}
AND B.ITEM_CODE= #{SEARCH_KEY_WORD}
AND B.ITEM_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND B.ITEM_CODE LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
)

/* Top 5 rpt008_getCtrmQtyRate */ SELECT LABEL_VALUE ,CODE_VALUE ,CASE WHEN SUM(DATA_VALUE) OVER() = 0 THEN 0 ELSE ROUND(TO_NUMBER(DATA_VALUE / SUM(DATA_VALUE) OVER()),5)* 100 END AS DATA_VALUE FROM ( SELECT '구매확인서' AS LABEL_VALUE ,'PO' AS CODE_VALUE ,NVL(SUM(B.QY),0) AS DATA_VALUE FROM SUPT_DOC_HDR A INNER JOIN SUPT_DOC_ITEM B ON A.COMPANY_CODE = B.COMPANY_CODE AND A.DIVISION_CODE = B.DIVISION_CODE AND A.SUPT_DOC_CODE = B.SUPT_DOC_CODE INNER JOIN CUSTOMER_MODEL CM ON B.COMPANY_CODE = CM.COMPANY_CODE AND B.DIVISION_CODE = CM.DIVISION_CODE AND A.CUSTOMER_CODE = CM.CUSTOMER_CODE AND B.ITEM_CODE = CM.CUSTOMER_ITEM_CODE LEFT OUTER JOIN CTRM_TRGET_THNG TT ON A.COMPANY_CODE = TT.COMPANY_CODE AND A.DIVISION_CODE = TT.DIVISION_CODE AND CM.ITEM_CODE = TT.ITEM_CODE AND A.SUPT_DOC_NO = TT.BASIS_DOC_NO LEFT OUTER JOIN CTRM_THING_RAWMTRL TR ON A.COMPANY_CODE = TR.COMPANY_CODE AND A.DIVISION_CODE = TR.DIVISION_CODE AND CM.ITEM_CODE = TR.RAWMTRL_CODE AND A.SUPT_DOC_NO = TR.BASIS_DOC_NO WHERE A.SUPT_DATE BETWEEN #{SEARCH_FROM_DATE} AND #{SEARCH_TO_DATE} AND HS_CODE10 IS NOT NULL AND LENGTH(HS_CODE10) = 10 AND A.COMPANY_CODE = #{COMPANY_CODE}
AND B.ITEM_CODE= #{SEARCH_KEY_WORD}
AND B.ITEM_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND B.ITEM_CODE LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
UNION ALL SELECT '기납증/분증' AS LABEL_VALUE ,'CTRM' AS CODE_VALUE ,NVL(SUM(TT.ACCMLT_ORDER_QY),0) + NVL(SUM(TR.USGQTY),0) AS DATA_VALUE FROM SUPT_DOC_HDR A INNER JOIN SUPT_DOC_ITEM B ON A.COMPANY_CODE = B.COMPANY_CODE AND A.DIVISION_CODE = B.DIVISION_CODE AND A.SUPT_DOC_CODE = B.SUPT_DOC_CODE INNER JOIN CUSTOMER_MODEL CM ON B.COMPANY_CODE = CM.COMPANY_CODE AND B.DIVISION_CODE = CM.DIVISION_CODE AND A.CUSTOMER_CODE = CM.CUSTOMER_CODE AND B.ITEM_CODE = CM.CUSTOMER_ITEM_CODE LEFT OUTER JOIN CTRM_TRGET_THNG TT ON A.COMPANY_CODE = TT.COMPANY_CODE AND A.DIVISION_CODE = TT.DIVISION_CODE AND CM.ITEM_CODE = TT.ITEM_CODE AND A.SUPT_DOC_NO = TT.BASIS_DOC_NO LEFT OUTER JOIN CTRM_THING_RAWMTRL TR ON A.COMPANY_CODE = TR.COMPANY_CODE AND A.DIVISION_CODE = TR.DIVISION_CODE AND CM.ITEM_CODE = TR.RAWMTRL_CODE AND A.SUPT_DOC_NO = TR.BASIS_DOC_NO WHERE A.SUPT_DATE BETWEEN #{SEARCH_FROM_DATE} AND #{SEARCH_TO_DATE} AND HS_CODE10 IS NOT NULL AND LENGTH(HS_CODE10) = 10 AND A.COMPANY_CODE = #{COMPANY_CODE}
AND B.ITEM_CODE= #{SEARCH_KEY_WORD}
AND B.ITEM_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND B.ITEM_CODE LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
)

SELECT B.XPORT_STTEMNT_NO AS STTEMNT_NO ,A.MANUFAC_NAME ,A.COMPANY_CODE ,B.ITEM_CODE ,B.ITEM_NM ,A.HS_CODE ,B.STTEMNT_PC_KRW ,B.ACCMLT_ORDER_QY ,TRUNC(SUM(NVL(D.CSTMS,0) + NVL(D.INTTAX,0) + NVL(D.ECX_AMOUNT,0) + NVL(D.AGSPT,0) + NVL(D.TRANTAX,0) + NVL(D.LQTX_AMOUNT,0)),-1) AS TOT_TAX ,TRUNC(SUM(C.DRWBAK_AMOUNT),-1) AS DRWBAK_AMOUNT ,SUM(C.USGQTY) AS USGQTY ,M.NATION_CODE FROM DRWBAK_REQSTDOC_CMMN A INNER JOIN DRWBAK_REQSTDOC_TRGET_THNG B ON A.PRESENTN_NO = B.PRESENTN_NO AND A.COMPANY_CODE = B.COMPANY_CODE INNER JOIN DRWBAK_REQSTDOC_INCME_RAWMTRL C ON B.COMPANY_CODE = C.COMPANY_CODE AND B.PRESENTN_NO = C.PRESENTN_NO AND B.THNG_SEQ = C.THNG_SEQ INNER JOIN EXPORT_CERT_MST M ON M.COMPANY_CODE = B.COMPANY_CODE AND M.DIVISION_CODE = B.DIVISION_CODE AND M.XPORT_STTEMNT_NO = B.XPORT_STTEMNT_NO AND M.LNE_NO = B.LNE_NO AND M.POUCH_NO = B.POUCH_NO AND M.ITEM_CODE = B.ITEM_CODE
INNER JOIN INCME_LOCAL_BNT_SM D ON D.COMPANY_CODE = C.COMPANY_CODE AND D.IMPDEC_NO = C.IMPDEC_NO AND D.LNE_NO = C.LNE_NO AND D.POUCH_NO = C.POUCH_NO AND D.ITEM_CODE = C.RAWMTRL_CODE WHERE A.COMPANY_CODE = #{COMPANY_CODE}
AND M.MANUFAC_NAME = #{DETAIL_CODE}
AND M.ITEM_CODE = #{DETAIL_CODE}
AND A.HS_CODE = #{DETAIL_CODE}
AND M.NATION_CODE = #{DETAIL_CODE}
AND M.ITEM_CODE= #{SEARCH_KEY_WORD}
AND M.ITEM_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND M.ITEM_CODE LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
AND M.DSPTH_DATE BETWEEN #{SEARCH_FROM_DATE} AND #{SEARCH_TO_DATE}
GROUP BY B.XPORT_STTEMNT_NO ,A.MANUFAC_NAME ,A.COMPANY_CODE ,B.ITEM_CODE ,B.ITEM_NM ,A.HS_CODE ,B.STTEMNT_PC_KRW ,B.ACCMLT_ORDER_QY ,M.NATION_CODE

SELECT A.IMPDEC_MANAGE_NO AS STTEMNT_NO , NVL(A.SUPLER_MTLTY_1,V.VENDOR_NAME) AS MANUFAC_NAME , A.COMPANY_CODE , B.ITEM_CODE , B.ITEM_NM , B.HS_CODE , B.CVODV_KRW AS STTEMNT_PC_KRW , A.OVSEA_SUPLER_NATION_CODE AS NATION_CODE , TRUNC(SUM(NVL(L.CSTMS, 0) + NVL(L.INTTAX, 0) + NVL(L.ECX_AMOUNT, 0) + NVL(L.AGSPT, 0) + NVL(L.TRANTAX, 0) + NVL(L.LQTX_AMOUNT, 0)),-1) AS TOT_TAX , TRUNC(SUM(NVL(XC.CSTMS, 0) + NVL(XC.INTTAX, 0) + NVL(XC.ECX_AMOUNT, 0) + NVL(XC.AGSPT, 0) + NVL(XC.TRANTAX, 0) + NVL(XC.LQTX_AMOUNT, 0)),-1) AS DRWBAK_AMOUNT /* , B.QY AS ACCMLT_ORDER_QY , TRUNC(SUM(CASE WHEN B.BASS_UNIT = XC.BASS_UNIT THEN XC.USGQTY ELSE (CASE WHEN B.BASS_UNIT = 'KG' THEN XC.USGQTY / 1000 WHEN B.BASS_UNIT = 'LB' THEN XC.USGQTY / 0.453592 / 1000 WHEN B.BASS_UNIT = 'DR' THEN XC.USGQTY / 1000 / 30 WHEN B.BASS_UNIT = 'GR' THEN XC.USGQTY / 0.064799 WHEN B.BASS_UNIT = 'MT' THEN XC.USGQTY / 1000 / 1000 ELSE B.QY END) END),2) AS USGQTY */ , TRUNC(SUM(NVL(L.QY,0))) AS ACCMLT_ORDER_QY , TRUNC(SUM(NVL(L.DLIVY_QY,0))) AS USGQTY FROM IMPDEC_CERFIN_HDER A INNER JOIN IMPDEC_CERFIN_ITEM B ON A.COMPANY_CODE = B.COMPANY_CODE AND A.DIVISION_CODE = B.DIVISION_CODE AND A.IMPDEC_NO = B.IMPDEC_NO INNER JOIN INCME_LOCAL_BNT_SM L ON B.COMPANY_CODE = L.COMPANY_CODE AND B.DIVISION_CODE = L.DIVISION_CODE AND B.IMPDEC_NO = L.IMPDEC_NO AND B.LNE_NO = L.LNE_NO AND B.POUCH_NO = L.POUCH_NO LEFT OUTER JOIN VENDOR V ON A.COMPANY_CODE = V.COMPANY_CODE AND A.VENDOR_CODE = V.VENDOR_CODE LEFT OUTER JOIN DRWBAK_REQSTDOC_INCME_RAWMTRL XC ON L.COMPANY_CODE = XC.COMPANY_CODE AND L.IMPDEC_NO = XC.IMPDEC_NO AND L.LNE_NO = XC.LNE_NO AND L.POUCH_NO = XC.POUCH_NO LEFT OUTER JOIN DRWBAK_REQSTDOC_TRGET_THNG XB ON XB.COMPANY_CODE = XC.COMPANY_CODE AND XB.PRESENTN_NO = XC.PRESENTN_NO AND XB.THNG_SEQ = XC.THNG_SEQ LEFT OUTER JOIN DRWBAK_REQSTDOC_CMMN XA ON XB.PRESENTN_NO = XA.PRESENTN_NO AND XB.COMPANY_CODE = XA.COMPANY_CODE WHERE A.COMPANY_CODE = #{COMPANY_CODE}
AND A.VENDOR_CODE = #{DETAIL_CODE}
AND B.ITEM_CODE= #{DETAIL_CODE}
AND B.HS_CODE = #{DETAIL_CODE}
AND A.OVSEA_SUPLER_NATION_CODE = #{DETAIL_CODE}
AND B.ITEM_CODE= #{SEARCH_KEY_WORD}
AND B.ITEM_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND B.ITEM_CODE LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
AND A.STTEMNT_DATE BETWEEN #{SEARCH_FROM_DATE} AND #{SEARCH_TO_DATE} GROUP BY A.IMPDEC_MANAGE_NO ,NVL(A.SUPLER_MTLTY_1,V.VENDOR_NAME) ,A.COMPANY_CODE ,B.ITEM_CODE ,B.ITEM_NM ,B.HS_CODE ,B.CVODV_KRW ,B.QY ,A.OVSEA_SUPLER_NATION_CODE

SELECT BL.LABEL_VALUE , BL.LABEL_NAME , NVL(VA.DATA_VALUE, 0) AS DATA_VALUE , DECODE((SUM(VA.DATA_VALUE) OVER()), 0 , 0, NVL(ROUND(VA.DATA_VALUE / (SUM(VA.DATA_VALUE) OVER()) * 100,2),0)) AS RATE_VALUE FROM CHART_LABEL BL LEFT OUTER JOIN ( SELECT 1 AS LABEL_SEQ , SUM(E.STTEMNT_PC_KRW) AS DATA_VALUE FROM EXPORT_CERT_MST E WHERE E.COMPANY_CODE = #{COMPANY_CODE} AND E.XPORT_SE IN ('11','17','31') AND (E.RQST_PRSN_CODE <> '2' OR (E.RQST_PRSN_CODE = '2' AND E.MANUFAC_NAME = '(주)아모레퍼시픽')) AND E.DSPTH_DATE BETWEEN #{SEARCH_FROM_DATE} AND #{SEARCH_TO_DATE} AND E.RQST_PRSN_CODE LIKE #{RQST_PRSN_CODE} || '%'
AND E.ITEM_CODE = #{SEARCH_KEY_WORD}
AND E.ITEM_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND E.ITEM_CODE LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
AND E.EXPDECL_MANAGE_NO = #{SEARCH_KEY_WORD_NO}
AND E.EXPDECL_MANAGE_NO LIKE #{SEARCH_KEY_WORD_NO}|| '%'
AND E.EXPDECL_MANAGE_NO LIKE '%'||#{SEARCH_KEY_WORD_NO}|| '%'
AND E.MANUFAC_NAME = #{SEARCH_KEY_WORD_MAKER}
AND E.MANUFAC_NAME LIKE #{SEARCH_KEY_WORD_MAKER}|| '%'
AND E.MANUFAC_NAME LIKE '%'||#{SEARCH_KEY_WORD_MAKER}|| '%'
UNION ALL SELECT 2 AS LEBEL , SUM(STTEMNT_PC_KRW) AS DATA_VALUE FROM EXPORT_CERT_MST E WHERE E.COMPANY_CODE = #{COMPANY_CODE} AND E.XPORT_SE IN ('11','17','31') AND E.RQST_PRSN_CODE = '2' AND E.MANUFAC_NAME <> '(주)아모레퍼시픽' AND E.DSPTH_DATE BETWEEN #{SEARCH_FROM_DATE} AND #{SEARCH_TO_DATE} AND E.RQST_PRSN_CODE LIKE #{RQST_PRSN_CODE} || '%'
AND E.ITEM_CODE = #{SEARCH_KEY_WORD}
AND E.ITEM_CODE LIKE #{SEARCH_KEY_WORD}|| '%'
AND E.ITEM_CODE LIKE '%'||#{SEARCH_KEY_WORD}|| '%'
AND E.EXPDECL_MANAGE_NO = #{SEARCH_KEY_WORD_NO}
AND E.EXPDECL_MANAGE_NO LIKE #{SEARCH_KEY_WORD_NO}|| '%'
AND E.EXPDECL_MANAGE_NO LIKE '%'||#{SEARCH_KEY_WORD_NO}|| '%'
AND E.MANUFAC_NAME = #{SEARCH_KEY_WORD_MAKER}
AND E.MANUFAC_NAME LIKE #{SEARCH_KEY_WORD_MAKER}|| '%'
AND E.MANUFAC_NAME LIKE '%'||#{SEARCH_KEY_WORD_MAKER}|| '%'
) VA ON BL.LABEL_SEQ = VA.LABEL_SEQ WHERE LABEL_ID = #{LABEL_ID}

SELECT BL.LABEL_VALUE , BL.LABEL_NAME , NVL(VA.DATA_VALUE, 0) AS DATA_VALUE , DECODE((SUM(VA.DATA_VALUE) OVER()), 0 , 0, NVL(ROUND(VA.DATA_VALUE / (SUM(VA.DATA_VALUE) OVER()) * 100,2),0)) AS RATE_VALUE FROM CHART_LABEL BL LEFT OUTER JOIN ( SELECT 1 AS LABEL_SEQ , COUNT(DISTINCT E.EXPDECL_MANAGE_NO) AS DATA_VALUE FROM EXPORT_CERT_MST E WHERE E.COMPANY_CODE = #{COMPANY_CODE} AND E.XPORT_SE IN ('11','17','31') AND (E.RQST_PRSN_CODE <> '2' OR (E.RQST_PRSN_CODE = '2' AND E.MANUFAC_NAME = '(주)아모레퍼시픽')) AND E.DSPTH_DATE BETWEEN #{SEARCH_FROM_DATE} AND #{SEARCH_TO_DATE} AND E.RQST_PRSN_CODE LIKE #{RQST_PRSN_CODE} || '%'
