SELECT BL.LABEL_VALUE , BL.LABEL_NAME , NVL(VA.DATA_VALUE, 0) AS DATA_VALUE , DECODE((SUM(VA.DATA_VALUE) OVER()), 0 , 0, NVL(ROUND(VA.DATA_VALUE / (SUM(VA.DATA_VALUE) OVER()) * 100,2),0)) AS RATE_VALUE FROM CHART_LABEL BL LEFT OUTER JOIN ( SELECT 1 AS LABEL_SEQ , SUM((SELECT SUM(DRWBAK_AMOUNT) FROM DRWBAK_REQSTDOC_TRGET_THNG A , DRWBAK_REQSTDOC_INCME_RAWMTRL B WHERE A.COMPANY_CODE = B.COMPANY_CODE AND A.PRESENTN_NO = B.PRESENTN_NO AND A.THNG_SEQ = B.THNG_SEQ AND A.XPORT_STTEMNT_NO = E.EXPDECL_MANAGE_NO AND A.ITEM_CODE = E.ITEM_CODE)) AS DATA_VALUE FROM EXPORT_CERT_MST E WHERE E.COMPANY_CODE = #{COMPANY_CODE} AND E.XPORT_SE IN ('11','17','31') AND (E.RQST_PRSN_CODE <> '2' OR (E.RQST_PRSN_CODE = '2' AND E.MANUFAC_NAME = '(주)아모레퍼시픽')) AND E.DSPTH_DATE BETWEEN #{SEARCH_FROM_DATE} AND #{SEARCH_TO_DATE} AND E.RQST_PRSN_CODE LIKE #{RQST_PRSN_CODE} || '%'
AND E.ITEM_CODE = #{SEARCH_KEY_WORD}
